-- OTOTR FRANCHISE CONTRACT CREATE RPC CANDIDATE
create or replace function finance_private.current_franchise_contract_committer_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.resolve_franchise_contract_create_scope(p_actor_id uuid,p_legal_entity_id uuid,p_dealer_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_permission text) returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_api.authorize_franchise_contract_create(p_legal_entity_id uuid,p_dealer_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_permission text) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and p_permission='finance.contracts.create' and finance_private.resolve_franchise_contract_create_scope(auth.uid(),p_legal_entity_id,p_dealer_legal_entity_id,p_dealer_account_id,p_branch_id,p_permission)$$;
create or replace function finance_api.commit_franchise_contract_create(p_actor_id uuid,p_legal_entity_id uuid,p_dealer_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_contract_code text,p_reference_hash text,p_document_ids uuid[],p_idempotency_key text,p_intent_hash text,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_private as $$
declare v_id uuid:=gen_random_uuid();v_existing record;v_docs integer;v_payload jsonb;v_previous text;v_audit text;
begin
 if not finance_private.current_franchise_contract_committer_is_trusted() then raise exception using errcode='42501',message='trusted franchise contract committer required';end if;
 if pg_catalog.length(pg_catalog.btrim(coalesce(p_contract_code,''))) not between 1 and 200 or p_reference_hash!~'^[a-fA-F0-9]{64}$' or pg_catalog.length(pg_catalog.btrim(coalesce(p_idempotency_key,''))) not between 8 and 200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' then raise exception using errcode='22023',message='invalid franchise contract create command';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('contract-create:'||p_legal_entity_id::text||':'||p_idempotency_key,0));
 select om.aggregate_id,om.payload into v_existing from finance.outbox_messages om where om.legal_entity_id=p_legal_entity_id and om.event_type='FRANCHISE_CONTRACT_DRAFT_CREATED' and om.payload->>'idempotencyKey'=p_idempotency_key order by om.created_at_utc desc,om.id desc limit 1;
 if found then if v_existing.payload->>'intentHash'=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','contractId',v_existing.aggregate_id,'dealerLegalEntityId',p_dealer_legal_entity_id,'contractCode',p_contract_code,'status','DRAFT','draftVersionId',null,'activeVersionId',null,'version',1);end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if not exists(select 1 from finance.dealer_legal_entities dle join finance.dealer_accounts da on da.legal_entity_id=dle.legal_entity_id and da.dealer_legal_entity_id=dle.id join finance.branches b on b.legal_entity_id=dle.legal_entity_id and b.dealer_legal_entity_id=dle.id where dle.id=p_dealer_legal_entity_id and dle.legal_entity_id=p_legal_entity_id and da.id=p_dealer_account_id and b.id=p_branch_id) then raise exception using errcode='42501',message='contract three dimensional scope denied';end if;
 select pg_catalog.count(distinct dr.external_document_id) into v_docs from finance.document_references dr where dr.legal_entity_id=p_legal_entity_id and dr.status='ACTIVE' and dr.external_document_id=any(coalesce(p_document_ids,array[]::uuid[]));if v_docs<>coalesce(pg_catalog.cardinality(p_document_ids),0) then raise exception using errcode='23514',message='all contract documents must be active';end if;
 if exists(select 1 from finance.franchise_contracts fc where fc.legal_entity_id=p_legal_entity_id and fc.contract_code=p_contract_code) then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 insert into finance.franchise_contracts(id,legal_entity_id,dealer_legal_entity_id,contract_code,status,version,created_by,correlation_id) values(v_id,p_legal_entity_id,p_dealer_legal_entity_id,p_contract_code,'DRAFT',1,p_actor_id,p_correlation_id);
 insert into finance.document_links(legal_entity_id,document_reference_id,subject_type,subject_id,purpose_code,created_by,correlation_id) select p_legal_entity_id,dr.id,'FRANCHISE_CONTRACT',v_id,'CONTRACT_EVIDENCE_V1',p_actor_id,p_correlation_id from finance.document_references dr where dr.legal_entity_id=p_legal_entity_id and dr.status='ACTIVE' and dr.external_document_id=any(coalesce(p_document_ids,array[]::uuid[]));
 v_payload:=pg_catalog.jsonb_build_object('contractId',v_id,'dealerLegalEntityId',p_dealer_legal_entity_id,'dealerAccountId',p_dealer_account_id,'branchId',p_branch_id,'referenceHash',p_reference_hash,'documentCount',v_docs,'idempotencyKey',p_idempotency_key,'intentHash',p_intent_hash);
 insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p_legal_entity_id,'finance.contract','FRANCHISE_CONTRACT_DRAFT_CREATED','FRANCHISE_CONTRACT',v_id,1,v_payload,p_intent_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p_legal_entity_id::text,0));select integrity_hash into v_previous from finance.audit_events where legal_entity_id=p_legal_entity_id order by created_at_utc desc,id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||v_id::text||':FRANCHISE_CONTRACT_DRAFT_CREATED:'||p_intent_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');
 insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p_legal_entity_id,p_actor_id,'USER','FRANCHISE_CONTRACT_DRAFT_CREATED','FRANCHISE_CONTRACT',v_id,'ALLOW',p_intent_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('dealerLegalEntityId',p_dealer_legal_entity_id,'branchId',p_branch_id,'referenceHash',p_reference_hash,'documentCount',v_docs),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','CREATED','contractId',v_id,'dealerLegalEntityId',p_dealer_legal_entity_id,'contractCode',p_contract_code,'status','DRAFT','draftVersionId',null,'activeVersionId',null,'version',1);
end$$;
revoke all on function finance_private.current_franchise_contract_committer_is_trusted() from public,anon,authenticated;revoke all on function finance_private.resolve_franchise_contract_create_scope(uuid,uuid,uuid,uuid,uuid,text) from public,anon,authenticated;revoke all on function finance_api.authorize_franchise_contract_create(uuid,uuid,uuid,uuid,text) from public,anon;grant execute on function finance_api.authorize_franchise_contract_create(uuid,uuid,uuid,uuid,text) to authenticated;revoke all on function finance_api.commit_franchise_contract_create(uuid,uuid,uuid,uuid,uuid,text,text,uuid[],text,text,uuid) from public,anon,authenticated;
